if set(_HELP_POST_CONTROL_ROWS) != {
    code for code, _label in LANGUAGE_OPTIONS if code != "en"
}:
    raise ValueError(
        "Help-post control catalogs must cover all offered non-English locales"
    )

HELP_POST_CONTROL_CATALOGS: dict[str, dict[str, str]] = {
    language: dict(zip(HELP_POST_CONTROL_KEYS, row.split("|"), strict=True))
    for language, row in _HELP_POST_CONTROL_ROWS.items()
}

if len(HELP_POST_CONTROL_KEYS) != 32 or len(set(HELP_POST_CONTROL_KEYS)) != 32:
    raise ValueError(
        "Help-post control source keys must contain 32 unique entries"
    )
